33	// Selects which end of an allocator's pre-allocated address range a request
34	// should be served from, for allocators that spatially partition their range.
35	// Allocators that do not spatially partition ignore this and always behave as
36	// kLower.
37	enum class AllocationEnd : uint8_t {
38	  kLower,  // Carve from the lower-address end of the range (grows up).
39	  kUpper,  // Carve from the upper-address end of the range (grows down).
40	};
41	
42	template <typename Sink>
43	void AbslStringify(Sink& sink, AllocationEnd end) {
44	  switch (end) {
45	    case AllocationEnd::kLower:
46	      sink.Append("lower");
47	      return;
48	    case AllocationEnd::kUpper:
49	      sink.Append("upper");
50	      return;
51	  }
52	}
53	
54	// Attributes for a single allocation call. Different calls to the same
55	// allocator could potentially have different allocation attributes.
56	struct AllocationAttributes {
57	  AllocationAttributes() = default;
58	
59	  AllocationAttributes(bool retry_on_failure, bool allocation_will_be_logged,
60	                       std::function<uint64_t()>* freed_by_func,
61	                       AllocationEnd allocation_end = AllocationEnd::kLower)
62	      : retry_on_failure(retry_on_failure),
63	        allocation_will_be_logged(allocation_will_be_logged),
64	        freed_by_func(freed_by_func),
65	        allocation_end(allocation_end) {}
66	
67	  // If the first attempt to allocate the memory fails, the allocation should
68	  // wait and retry (with a timeout).
69	  //
70	  // This is usually set to true, but we may set it to false in cases where a
71	  // failure has only performance impact (e.g. optional scratch space
72	  // allocation).
73	  bool retry_on_failure = true;
74	  // If a Tensor is allocated without the following set to true, then
75	  // it is logged as an unknown allocation. During execution Tensors
76	  // should be allocated through the OpKernelContext which records
77	  // which Op is performing the allocation, and sets this flag to
78	  // true.
79	  bool allocation_will_be_logged = false;
80	  // EXPERIMENTAL: If provided, then evaluates to a timing count such that only
81	  // a memory chunk whose freed_at_count is at this value or earlier may be
82	  // returned.
83	  std::function<uint64_t()>* freed_by_func = nullptr;  // Not owned.
84	
85	  // Which end of the allocator's pre-allocated address range to serve this
86	  // request from. Only honored by allocators configured for spatial
87	  // partitioning.
88	  AllocationEnd allocation_end = AllocationEnd::kLower;
89	
90	  AllocationAttributes(const AllocationAttributes&) = delete;
91	  void operator=(const AllocationAttributes&) = delete;
92	};
93	
94	// Runtime statistics collected by an allocator. Exactly the same as
95	// stream_executor::AllocatorStats, but independently defined to preserve the
96	// mutual independence of StreamExecutor and TensorFlow.
97	struct AllocatorStats {
98	  int64_t num_allocs;          // Number of allocations.
99	  int64_t bytes_in_use;        // Number of bytes in use.
100	  int64_t peak_bytes_in_use;   // The peak bytes in use.
101	  int64_t largest_alloc_size;  // The largest single allocation seen.
102	
103	  // The upper limit of bytes of user allocatable device memory, if such a limit
104	  // is known.
105	  std::optional<int64_t> bytes_limit;
106	
107	  // Stats for reserved memory usage.
108	  int64_t bytes_reserved;       // Number of bytes reserved.
109	  int64_t peak_bytes_reserved;  // The peak number of bytes reserved.
110	  int64_t peak_allocated_bytes;  // Peak of reserved and in-use bytes.
111	  // The upper limit on the number bytes of reservable memory,
112	  // if such a limit is known.
113	  std::optional<int64_t> bytes_reservable_limit;
114	
115	  int64_t largest_free_block_bytes;  // Largest free block's size in heap.
116	
117	  // Number of bytes of memory held by the allocator.  This may be higher than
118	  // bytes_in_use if the allocator holds a pool of memory (e.g. BFCAllocator).
119	  std::optional<int64_t> pool_bytes;
120	  std::optional<int64_t> peak_pool_bytes;
121	
122	  AllocatorStats()
123	      : num_allocs(0),
124	        bytes_in_use(0),
125	        peak_bytes_in_use(0),
126	        largest_alloc_size(0),
127	        bytes_reserved(0),
128	        peak_bytes_reserved(0),
129	        peak_allocated_bytes(0),
130	        largest_free_block_bytes(0) {}
131	
132	  std::string DebugString() const;
133	};
134	
135	// The type of the allocated memory.
136	enum class AllocatorMemoryType {
137	  kUnknown = 0,       // Memory type unknown.
138	  kDevice = 1,        // Memory on device.
139	  kHostPageable = 2,  // Memory on host and it is pageable.
140	  kHostPinned = 3,    // Memory on host and it is pinned.
141	};
142	
143	// Allocator is an abstract interface for allocating and deallocating
144	// device memory.
145	class Allocator {
146	 public:
147	  // Align to 64 byte boundary.
148	  static constexpr size_t kAllocatorAlignment = 64;
149	
150	  virtual ~Allocator();
151	
152	  // Return a string identifying this allocator
153	  virtual std::string Name() = 0;
154	
155	  // Return an uninitialized block of memory that is "num_bytes" bytes
156	  // in size.  The returned pointer is guaranteed to be aligned to a
157	  // multiple of "alignment" bytes.
158	  // REQUIRES: "alignment" is a power of 2.
159	  virtual void* AllocateRaw(size_t alignment, size_t num_bytes) = 0;
160	
161	  // Return an uninitialized block of memory that is "num_bytes" bytes
162	  // in size with specified allocation attributes.  The returned pointer is
163	  // guaranteed to be aligned to a multiple of "alignment" bytes.
164	  // REQUIRES: "alignment" is a power of 2.
165	  virtual void* AllocateRaw(size_t alignment, size_t num_bytes,
166	                            const AllocationAttributes& allocation_attr) {
167	    // The default behavior is to use the implementation without any allocation
168	    // attributes.
169	    return AllocateRaw(alignment, num_bytes);
170	  }
171	
172	  // Return an uninitialized block of memory that is "num_bytes" bytes
173	  // in size. The returned pointer is guaranteed to be aligned to a
174	  // multiple of "alignment" bytes. This version indicates alignment will be
175	  // passed to the DeallocateRawAlignedDelete invocation.
176	  // The default implementation calls the original AllocateRaw. Derived classes
177	  // can take advantage of the interface guarantees to invoke AlignedNew.
178	  // REQUIRES: "alignment" is a power of 2.
179	  virtual void* AllocateRawAlignedNew(size_t alignment, size_t num_bytes) {
180	    return AllocateRaw(alignment, num_bytes);
181	  }
182	
183	  virtual void* AllocateRawAlignedNew(
184	      size_t alignment, size_t num_bytes,
185	      const AllocationAttributes& allocation_attr) {
186	    return AllocateRaw(alignment, num_bytes, allocation_attr);
187	  }
188	
189	  // Deallocate a block of memory pointer to by "ptr"
190	  // REQUIRES: "ptr" was previously returned by a call to AllocateRaw
191	  virtual void DeallocateRaw(void* ptr) = 0;
192	
193	  virtual void DeallocateRaw(void* ptr, size_t alignment, size_t num_bytes) {
194	    (void)alignment;
195	    (void)num_bytes;
196	
197	    DeallocateRaw(ptr);
198	  }
199	
200	  // Deallocate a block of memory pointed to by "ptr".
201	  // The default implementation calls the original DeallocateRaw. Derived
202	  // classes can take advantage of the interface guarantees to invoke
203	  // AlignedDelete.
204	  virtual void DeallocateRawAlignedDelete(void* ptr, size_t alignment,
205	                                          size_t num_bytes) {
206	    DeallocateRaw(ptr, alignment, num_bytes);
207	  }
208	
209	  // Returns true if this allocator tracks the sizes of allocations.
210	  // RequestedSize and AllocatedSize must be overridden if
211	  // TracksAllocationSizes is overridden to return true.
212	  virtual bool TracksAllocationSizes() const { return false; }
213	
214	  // Returns true if this allocator allocates an opaque handle rather than the
215	  // requested number of bytes.
216	  //
217	  // This method returns false for most allocators, but may be used by
218	  // special-case allocators that track tensor usage. If this method returns
219	  // true, AllocateRaw() should be invoked for all values of `num_bytes`,
220	  // including 0.
221	  //
222	  // NOTE: It is the caller's responsibility to track whether an allocated
223	  // object is a buffer or an opaque handle. In particular, when this method
224	  // returns `true`, users of this allocator must not run any constructors or
225	  // destructors for complex objects, since there is no backing store for the
226	  // tensor in which to place their outputs.
227	  virtual bool AllocatesOpaqueHandle() const { return false; }
228	
229	  // Returns the user-requested size of the data allocated at
230	  // 'ptr'.  Note that the actual buffer allocated might be larger
231	  // than requested, but this function returns the size requested by
232	  // the user.
233	  //
234	  // REQUIRES: TracksAllocationSizes() is true.
235	  //
236	  // REQUIRES: 'ptr!=nullptr' and points to a buffer previously
237	  // allocated by this allocator.
238	  virtual size_t RequestedSize(const void* ptr) const {
239	    CHECK(false) << "allocator doesn't track sizes";
240	    return size_t(0);
241	  }
242	
243	  // Returns the allocated size of the buffer at 'ptr' if known,
244	  // otherwise returns RequestedSize(ptr). AllocatedSize(ptr) is
245	  // guaranteed to be >= RequestedSize(ptr).
246	  //
247	  // REQUIRES: TracksAllocationSizes() is true.
248	  //
249	  // REQUIRES: 'ptr!=nullptr' and points to a buffer previously
250	  // allocated by this allocator.
251	  virtual size_t AllocatedSize(const void* ptr) const {
252	    return RequestedSize(ptr);
253	  }
254	
255	  // Returns either 0 or an identifier assigned to the buffer at 'ptr'
256	  // when the buffer was returned by AllocateRaw. If non-zero, the
257	  // identifier differs from every other ID assigned by this
258	  // allocator.
259	  //
260	  // REQUIRES: TracksAllocationSizes() is true.
261	  //
262	  // REQUIRES: 'ptr!=nullptr' and points to a buffer previously
263	  // allocated by this allocator.
264	  virtual int64_t AllocationId(const void* ptr) const { return 0; }
265	
266	  // Returns the allocated size of the buffer at 'ptr' if known,
267	  // otherwise returns 0. This method can be called when
268	  // TracksAllocationSizes() is false, but can be extremely slow.
269	  //
270	  // REQUIRES: 'ptr!=nullptr' and points to a buffer previously
271	  // allocated by this allocator.
272	  virtual size_t AllocatedSizeSlow(const void* ptr) const {
273	    if (TracksAllocationSizes()) {
274	      return AllocatedSize(ptr);
275	    }
276	    return 0;
277	  }
278	
279	  // Fills in 'stats' with statistics collected by this allocator.
280	  virtual std::optional<AllocatorStats> GetStats() { return std::nullopt; }
281	
282	  // If implemented, clears the internal stats except for the `in_use` fields
283	  // and sets the `peak_bytes_in_use` to be equal to the `bytes_in_use`. Returns
284	  //  true if implemented.
285	  //
286	  // REQUIRES: GetStats is overridden.
287	  virtual bool ClearStats() TF_MUST_USE_RESULT { return false; }
288	
289	  virtual void SetSafeFrontier(uint64_t count) {}
290	
291	  // For allocator that are stream aware, allow to specify the compute
292	  // stream this allocator is used for. This can also trigger memory
293	  // preallocation.
294	  virtual void SetStreamAndPreallocateMemory(void* stream) {}
295	
296	  // Returns the type of the memory allocated by this allocator.
297	  virtual AllocatorMemoryType GetMemoryType() const {
298	    return AllocatorMemoryType::kUnknown;
299	  }
300	};
301	
302	// An implementation of Allocator that delegates all calls to another Allocator.
303	//
304	// Useful to clients who want to override part of the functionality of another
305	// allocator.
306	class AllocatorWrapper : public Allocator {
307	 public:
308	  explicit AllocatorWrapper(Allocator* wrapped) : wrapped_(wrapped) {}
309	
310	  ~AllocatorWrapper() override = default;
311	
312	  // Returns the wrapped allocator to which all calls are delegated.
313	  Allocator* wrapped() const { return wrapped_; }
314	
315	  std::string Name() override { return wrapped_->Name(); }
316	
317	  void* AllocateRaw(size_t alignment, size_t num_bytes) override {
318	    return wrapped_->AllocateRaw(alignment, num_bytes);
319	  }
320	
321	  void* AllocateRaw(size_t alignment, size_t num_bytes,
322	                    const AllocationAttributes& allocation_attr) override {
323	    return wrapped_->AllocateRaw(alignment, num_bytes, allocation_attr);
324	  }
325	
326	  void DeallocateRaw(void* ptr) override { wrapped_->DeallocateRaw(ptr); }
327	
328	  bool TracksAllocationSizes() const override {
329	    return wrapped_->TracksAllocationSizes();
330	  }
331	
332	  bool AllocatesOpaqueHandle() const override {
333	    return wrapped_->AllocatesOpaqueHandle();
334	  }
335	
336	  size_t RequestedSize(const void* ptr) const override {
337	    return wrapped_->RequestedSize(ptr);
338	  }
339	
340	  size_t AllocatedSize(const void* ptr) const override {
341	    return wrapped_->AllocatedSize(ptr);
342	  }
343	
344	  int64_t AllocationId(const void* ptr) const override {
345	    return wrapped_->AllocationId(ptr);
346	  }
347	
348	  size_t AllocatedSizeSlow(const void* ptr) const override {
349	    return wrapped_->AllocatedSizeSlow(ptr);
350	  }
351	
352	  AllocatorMemoryType GetMemoryType() const override {
353	    return wrapped_->GetMemoryType();
354	  }
355	
356	 private:
357	  Allocator* const wrapped_;
358	};
359	
360	// A tensorflow Op may need access to different kinds of memory that
361	// are not simply a function of the device to which the Op has been
362	// assigned.  For example, an Op executing on a GPU may still need
363	// to allocate CPU RAM for some purpose.  Internal to the tensorflow
364	// runtime we may choose to allocate CPU ram from special regions
365	// that have been prepared for higher performance in some use
366	// contexts, e.g. doing DMA with particular devices.  For these
367	// reasons, the Device interface does not expose just one memory
368	// Allocator, but instead provides an accessor that takes a
369	// specification of the desired memory attributes in order to select
370	// an Allocator.
371	//
372	// Example use:
373	//  // Allocator for ordinary device memory:
374	//  Allocator* a = allocator(AllocatorAttributes());
375	// ...
376	//  // Allocator for CPU RAM, regardless of where Op is executing:
377	//  AllocatorAttributes attr;
378	//  attr.set_on_host(true);
379	//  Allocator* a = allocator(attr);
380	struct AllocatorAttributes {
381	  void set_on_host(bool v) { value |= (static_cast<int>(v)); }
382	  bool on_host() const { return value & 0x1; }
383	  void set_nic_compatible(bool v) { value |= (static_cast<int>(v) << 1); }
384	  bool nic_compatible() const { return value & (0x1 << 1); }
385	  void set_gpu_compatible(bool v) { value |= (static_cast<int>(v) << 2); }
386	  bool gpu_compatible() const { return value & (0x1 << 2); }
387	  void set_use_pjrt_allocator(bool v) { value |= (static_cast<int>(v) << 3); }
388	  bool use_pjrt_allocator() const { return value & (0x1 << 3); }
389	  void Merge(AllocatorAttributes other) {
390	    value |= other.value;
391	    if (scope_id != other.scope_id) {
392	      CHECK(scope_id == 0 || other.scope_id == 0)
393	          << "At least one scope_id should be zero to merge "
394	             "AllocatorAttributes but found this.scope_id="
395	          << scope_id << " and other.scope_id=" << other.scope_id;
396	      scope_id = scope_id == 0 ? other.scope_id : scope_id;
397	    }
398	  }
399	  // Returns true if the fields set in *this is a subset of or equal to
400	  // those set in other.
401	  bool IsEqualOrLessRestrictiveThan(const AllocatorAttributes& other) const {
402	    return (value | other.value) == other.value;
403	  }
404	
405	  // NOTE: The upper 8 bits of the value are reserved for
406	  // device-specific uses.  Implementors of a device can interpret these
407	  // upper 8 bits in device-specific ways, and ops implemented for those
408	  // devices are responsible for setting those 8 bits appropriately.
409	  uint32_t value = 0;
410	  // EXPERIMENTAL: If this is greater than zero, then allocation is delegated to
411	  // a named special-purpose allocator on the same device.
412	  int32_t scope_id = 0;
413	
414	  // Returns a human readable representation of this.
415	  std::string DebugString() const;
416	};
417	
418	// Returns a trivial implementation of Allocator, which is a process singleton.
419	// Access through this function is only intended for use by restricted parts
420	// of the infrastructure.
421	Allocator* cpu_allocator_base();
