423	// If available, calls ProcessState::GetCPUAllocator(numa_node).
424	// If not, falls back to cpu_allocator_base().
425	// Intended for use in contexts where ProcessState is not visible at
426	// compile time. Where ProcessState is visible, it's preferable to
427	// call it directly.
428	Allocator* cpu_allocator(int numa_node = port::kNUMANoAffinity);
