430	// Enables AllocatorStats in the default CPU allocator implementation.  By
431	// default, it's disabled.
432	void EnableCPUAllocatorStats();
433	// Disables AllocatorStats in the default CPU allocator implementation.  By
434	// default, it's disabled.
435	void DisableCPUAllocatorStats();
436	bool CPUAllocatorStatsEnabled();
