443	// An object that does the underlying suballoc/free of memory for a higher-level
444	// allocator.  The expectation is that the higher-level allocator is doing some
445	// kind of cache or pool management so that it will call SubAllocator::Alloc and
446	// Free relatively infrequently, compared to the number of times its own
447	// AllocateRaw and Free methods are called.
448	class SubAllocator {
449	 public:
450	  // Visitor gets called with a pointer to a memory area and its
451	  // size in bytes.  The index value will be numa_node for a CPU
452	  // allocator and GPU id for a GPU allocator.
453	  typedef std::function<void(void*, int index, size_t)> Visitor;
454	
455	  SubAllocator(const std::vector<Visitor>& alloc_visitors,
456	               const std::vector<Visitor>& free_visitors);
457	
458	  virtual ~SubAllocator() = default;
459	  // Allocates at least num_bytes. Returns actual number of bytes allocated in
460	  // bytes_received. The caller can safely use the full bytes_received sized
461	  // buffer following the returned pointer.
462	  virtual void* Alloc(size_t alignment, size_t num_bytes,
463	                      size_t* bytes_received) = 0;
464	  virtual void Free(void* ptr, size_t num_bytes) = 0;
465	
466	  // Returns true if the BFC allocator can safely coalesce adjacent regions
467	  // returned by this allocator.
468	  virtual bool SupportsCoalescing() const = 0;
469	
470	  // Returns the type of the memory allocated by this SubAllocator.
471	  virtual AllocatorMemoryType GetMemoryType() const {
472	    return AllocatorMemoryType::kUnknown;
473	  }
474	
475	 protected:
476	  // Implementation of Alloc() method must call this on newly allocated
477	  // value.
478	  void VisitAlloc(void* ptr, int index, size_t num_bytes);
479	
480	  // Implementation of Free() method must call this on value to be
481	  // freed immediately before deallocation.
482	  void VisitFree(void* ptr, int index, size_t num_bytes);
483	
484	  const std::vector<Visitor> alloc_visitors_;
485	  const std::vector<Visitor> free_visitors_;
486	};
487	
488	}  // namespace tsl
489	
490	#endif  // XLA_TSL_FRAMEWORK_ALLOCATOR_H_
