16	// Classes to maintain a static registry of memory allocator factories.
17	#ifndef XLA_TSL_FRAMEWORK_ALLOCATOR_REGISTRY_H_
18	#define XLA_TSL_FRAMEWORK_ALLOCATOR_REGISTRY_H_
19	
20	#include <memory>
