30	namespace tensorflow {
31	
32	class ProcessState;
33	
34	}
35	
36	namespace tsl {
37	
38	class AllocatorFactory {
39	 public:
40	  virtual ~AllocatorFactory() {}
41	
42	  // Returns true if the factory will create a functionally different
43	  // SubAllocator for different (legal) values of numa_node.
44	  virtual bool NumaEnabled() { return false; }
45	
46	  // Create an Allocator.
47	  virtual Allocator* CreateAllocator() = 0;
48	
49	  // Create a SubAllocator. If NumaEnabled() is true, then returned SubAllocator
50	  // will allocate memory local to numa_node.  If numa_node == kNUMANoAffinity
51	  // then allocated memory is not specific to any NUMA node.
52	  virtual SubAllocator* CreateSubAllocator(int numa_node) = 0;
53	};
54	
55	// ProcessState is defined in a package that cannot be a dependency of
56	// framework.  This definition allows us to access the one method we need.
57	class ProcessStateInterface {
58	 public:
59	  virtual ~ProcessStateInterface() {}
60	  virtual Allocator* GetCPUAllocator(int numa_node) = 0;
61	};
62	
63	// A singleton registry of AllocatorFactories.
64	//
65	// Allocators should be obtained through ProcessState or cpu_allocator()
66	// (deprecated), not directly through this interface.  The purpose of this
67	// registry is to allow link-time discovery of multiple AllocatorFactories among
68	// which ProcessState will obtain the best fit at startup.
69	class AllocatorFactoryRegistry {
70	 public:
71	  AllocatorFactoryRegistry() {}
72	  ~AllocatorFactoryRegistry() {}
73	
74	  void Register(const char* source_file, int source_line,
75	                const std::string& name, int priority,
76	                AllocatorFactory* factory);
77	
78	  // Returns 'best fit' Allocator.  Find the factory with the highest priority
79	  // and return an allocator constructed by it.  If multiple factories have
80	  // been registered with the same priority, picks one by unspecified criteria.
81	  Allocator* GetAllocator();
82	
83	  // Returns 'best fit' SubAllocator.  First look for the highest priority
84	  // factory that is NUMA-enabled.  If none is registered, fall back to the
85	  // highest priority non-NUMA-enabled factory.  If NUMA-enabled, return a
86	  // SubAllocator specific to numa_node, otherwise return a NUMA-insensitive
87	  // SubAllocator.
88	  SubAllocator* GetSubAllocator(int numa_node);
89	
90	  // Returns the singleton value.
91	  static AllocatorFactoryRegistry* singleton();
92	
93	  ProcessStateInterface* process_state() const {
94	    absl::MutexLock ml(mu_);
95	    return process_state_;
96	  }
97	
98	 protected:
99	  friend class tensorflow::ProcessState;
100	
101	  void SetProcessState(ProcessStateInterface* interface) {
102	    absl::MutexLock ml(mu_);
103	    process_state_ = interface;
104	  }
105	
106	 private:
107	  mutable absl::Mutex mu_;
108	  ProcessStateInterface* process_state_ ABSL_GUARDED_BY(mu_) = nullptr;
109	  bool first_alloc_made_ = false;
110	  struct FactoryEntry {
111	    const char* source_file;
112	    int source_line;
113	    std::string name;
114	    int priority;
115	    std::unique_ptr<AllocatorFactory> factory;
116	    std::unique_ptr<Allocator> allocator;
117	    // Index 0 corresponds to kNUMANoAffinity, other indices are (numa_node +
118	    // 1).
119	    std::vector<std::unique_ptr<SubAllocator>> sub_allocators;
120	  };
121	  std::vector<FactoryEntry> factories_ ABSL_GUARDED_BY(mu_);
122	
123	  // Returns any FactoryEntry registered under 'name' and 'priority',
124	  // or 'nullptr' if none found.
125	  const FactoryEntry* FindEntry(const std::string& name, int priority) const
126	      ABSL_EXCLUSIVE_LOCKS_REQUIRED(mu_);
127	
128	  AllocatorFactoryRegistry(const AllocatorFactoryRegistry&) = delete;
129	  void operator=(const AllocatorFactoryRegistry&) = delete;
130	};
131	
132	class AllocatorFactoryRegistration {
133	 public:
134	  AllocatorFactoryRegistration(const char* file, int line,
135	                               const std::string& name, int priority,
136	                               AllocatorFactory* factory) {
137	    AllocatorFactoryRegistry::singleton()->Register(file, line, name, priority,
138	                                                    factory);
139	  }
140	};
141	
142	#define REGISTER_MEM_ALLOCATOR(name, priority, factory)                     \
143	  REGISTER_MEM_ALLOCATOR_UNIQ_HELPER(__COUNTER__, __FILE__, __LINE__, name, \
144	                                     priority, factory)
145	
146	#define REGISTER_MEM_ALLOCATOR_UNIQ_HELPER(ctr, file, line, name, priority, \
147	                                           factory)                         \
148	  REGISTER_MEM_ALLOCATOR_UNIQ(ctr, file, line, name, priority, factory)
149	
150	#define REGISTER_MEM_ALLOCATOR_UNIQ(ctr, file, line, name, priority, factory) \
151	  static AllocatorFactoryRegistration allocator_factory_reg_##ctr(            \
152	      file, line, name, priority, new factory)
153	
154	}  // namespace tsl
