323	void* BFCAllocator::AllocateRaw(size_t alignment, size_t num_bytes,
324	                                const AllocationAttributes& allocation_attr) {
325	  VLOG(3) << "AllocateRaw " << Name() << " " << num_bytes
326	          << " alignment=" << alignment;
327	  // Only spatially partitioned allocators serve upper-end requests; everything
328	  // else must leave allocation_end at its kLower default. This lets the
329	  // allocation path skip partitioning branches: with allocation_end always
330	  // kLower, requests only ever land in AllocateChunkFromLowEnd.
331	  DCHECK(opts_.enable_spatial_partitioning ||
332	         allocation_attr.allocation_end == AllocationEnd::kLower);
333	  void* result = [&] {
334	    if (!opts_.allow_retry_on_failure || !allocation_attr.retry_on_failure) {
335	      // If we have globally disabled retry-on-failure and fail to allocate an
336	      // "important" alloc, we want to print a log, because the program may be
337	      // about to fail due to OOM.
338	      //
339	      // Bit of a hack: We deem "important" allocs as those which are retryable.
340	      // In TF, *non*-retryable allocations are usually those which we can
341	      // tolerate failing.  For example, we allocate convolution scratch memory
342	      // as non-retryable; if it fails, we'll just use a fallback algorithm that
343	      // uses no scratch.
344	      static std::atomic<int32_t> log_counter{0};
345	      constexpr int kMaxFailureLogs = 10;
346	      bool dump_log_on_failure =
347	          (/*retry is globally disabled*/ !opts_.allow_retry_on_failure &&
348	           /*alloc is "important"*/ allocation_attr.retry_on_failure &&
349	           log_counter.load(std::memory_order_relaxed) < kMaxFailureLogs) ||
350	          VLOG_IS_ON(2);
351	
352	      uint64_t freed_by_count = 0;
353	      if (allocation_attr.freed_by_func != nullptr) {
354	        freed_by_count = (*allocation_attr.freed_by_func)();
355	      }
356	      void* res =
357	          AllocateRawInternal(alignment, num_bytes, dump_log_on_failure,
358	                              freed_by_count, allocation_attr.allocation_end);
359	      if (res == nullptr) {
360	        int32_t counter_value = log_counter.load(std::memory_order_relaxed);
361	        if (counter_value < kMaxFailureLogs) {
362	          log_counter.store(counter_value + 1, std::memory_order_relaxed);
363	          LOG(WARNING)
364	              << "Allocator (" << Name() << ") ran out of memory trying "
365	              << "to allocate " << strings::HumanReadableNumBytes(num_bytes)
366	              << " from the " << allocation_attr.allocation_end << " end"
367	              << " with freed_by_count=" << freed_by_count << "."
368	              << (!allocation_attr.retry_on_failure
369	                      ? " The caller indicates that this is not a failure, but"
370	                        " this may mean that there could be performance gains "
371	                        "if more memory were available."
372	                      : "");
373	        }
374	      }
375	      return res;
376	    }
377	    return AllocateRawInternalWithRetry(alignment, num_bytes, allocation_attr);
378	  }();
379	  VLOG(3) << "AllocateRaw " << Name() << "  " << num_bytes << " " << result;
380	  VLOG(4) << "[mem-debug] AllocateRaw," << Name() << "," << num_bytes << ","
381	          << result << "," << tsl::CurrentStackTrace();
382	  return result;
383	}
