513	void* BFCAllocator::AllocateRawInternal(size_t alignment, size_t num_bytes,
514	                                        bool dump_log_on_failure,
515	                                        uint64_t freed_before,
516	                                        AllocationEnd allocation_end) {
517	  if (ABSL_PREDICT_FALSE(num_bytes == 0)) {
518	    VLOG(2) << "tried to allocate 0 bytes";
519	    return nullptr;
520	  }
521	  // First, always allocate memory of at least kMinAllocationSize
522	  // bytes, and always allocate multiples of kMinAllocationSize bytes
523	  // so all memory addresses are nicely byte aligned.
524	  size_t rounded_bytes = RoundedBytes(num_bytes);
525	
526	  // Alignment must be a power of two and at least kMinAllocationSize so that
527	  // splitting for alignment always produces kMinAllocationSize-aligned chunks.
