682	                                 size_t num_bytes, size_t alignment,
683	                                 uint64_t freed_before,
684	                                 AllocationEnd allocation_end) {
685	  // Spatial partitioning keeps three contiguous spans by address:
686	  //
687	  //   [ kLower (grows up) ][ kCentralGap ][ kUpper (grows down) ]
688	  //
689	  // A request first reuses a free hole with its own tag from the size bins.
690	  // Only if no same-tag hole fits does it carve from the one central gap.
691	  // Because neither end can create or consume the other end's interior holes,
692	  // lower placements are independent of upper activity and upper placements are
693	  // independent of lower activity, except when lower and upper allocations
694	  // exhaust the central gap.
695	  if (void* ptr = FindTaggedChunkPtr(bin_num, rounded_bytes, num_bytes,
696	                                     alignment, freed_before, allocation_end)) {
697	    return ptr;
698	  }
699	  return FindChunkPtrInCentralGap(rounded_bytes, num_bytes, alignment,
700	                                  freed_before, allocation_end);
701	}
