783	void* BFCAllocator::AllocateChunkFromLowEnd(ChunkHandle h, size_t rounded_bytes,
784	                                            size_t num_bytes,
785	                                            size_t alignment) {
786	  Chunk* chunk = ChunkFromHandle(h);
787	
788	  // If alignment requires it, split off the unaligned prefix as a separate free
789	  // chunk. For a central-gap carve, that prefix falls below the new lower
790	  // allocation and therefore becomes a lower-owned interior hole.
791	  uintptr_t ptr_int = absl::bit_cast<uintptr_t>(chunk->ptr);
792	  const size_t align_padding = LowEndAlignmentPadding(ptr_int, alignment);
793	  if (ABSL_PREDICT_FALSE(align_padding > 0)) {
794	    SplitChunk(h, align_padding);
795	    chunk = ChunkFromHandle(h);
796	    ChunkHandle aligned_h = chunk->next;
797	    RemoveFreeChunk(aligned_h);
798	    chunk->tag = ChunkTag::kLower;
799	    InsertFreeChunk(h);
800	    h = aligned_h;
801	    chunk = ChunkFromHandle(h);
802	  }
803	
804	  // If we can break the size of the chunk into two reasonably large pieces,
805	  // don't waste more than max_internal_fragmentation_bytes_ on padding. The
806	  // trailing remainder keeps the source chunk's tag (the central gap keeps its
807	  // tag; a lower hole stays lower).
808	  if (chunk->size >= rounded_bytes * 2 ||
809	      static_cast<int64_t>(chunk->size) - rounded_bytes >=
810	          max_internal_fragmentation_bytes_) {
811	    SplitChunk(h, rounded_bytes);
812	    chunk = ChunkFromHandle(h);  // Update chunk pointer in case it moved.
813	  }
814	
815	  // The in-use chunk gets the lower tag.
816	  chunk->tag = ChunkTag::kLower;
817	  FinishChunkAllocation(chunk, num_bytes);
818	  return chunk->ptr;
819	}
