394	  CHECK(absl::has_single_bit(alignment))
395	      << "alignment must be a power of 2, got " << alignment;
396	  const uintptr_t mask = static_cast<uintptr_t>(alignment) - 1;
397	  return (ptr + mask) & ~mask;
