422	bool BFCAllocator::DeallocateFreeRegions(size_t rounded_bytes)
423	    ABSL_EXCLUSIVE_LOCKS_REQUIRED(mutex_) {
424	  // Do nothing if garbage collection is off.
425	  if (!opts_.garbage_collection) {
426	    return false;
427	  }
428	
429	  // Searching for free regions.
430	  absl::flat_hash_set<void*> free_region_ptrs;
431	  size_t total_free_bytes = 0;
432	  for (const AllocationRegion& region : region_manager_.regions()) {
433	    ChunkHandle h = region_manager_.get_handle(region.ptr());
434	    bool any_use = false;
435	    while (h != kInvalidChunkHandle) {
436	      const Chunk* c = ChunkFromHandle(h);
437	      if (c->in_use()) {
438	        any_use = true;
439	        break;
440	      }
441	      h = c->next;
442	    }
443	
444	    if (!any_use) {
445	      VLOG(2) << "Found free region with ptr = " << region.ptr();
446	      free_region_ptrs.insert(region.ptr());
447	      total_free_bytes += region.memory_size();
448	    }
449	  }
450	
451	  if (total_free_bytes == 0) {
452	    return false;
453	  }
454	
455	  // Rough estimation to check whether deallocation can help.
456	  size_t available_bytes =
457	      memory_limit_ - *stats_.pool_bytes + total_free_bytes;
458	  if (rounded_bytes > available_bytes) {
459	    return false;
460	  }
461	
462	  LOG(WARNING) << "Garbage collection: deallocate free memory regions"
463	               << " (i.e., allocations) so that we can re-allocate a larger"
464	               << " region to avoid OOM due to memory fragmentation. If you"
465	               << " see this message frequently, you are running near the"
466	               << " threshold of the available device memory and re-allocation"
467	               << " may incur great performance overhead. You may try smaller"
468	               << " batch sizes to observe the performance impact."
469	               << " Set TF_ENABLE_GPU_GARBAGE_COLLECTION=false if you'd like to"
470	               << " disable this feature.";
471	
472	  // Deallocate free regions.
473	  DeallocateRegions(free_region_ptrs);
474	
475	  return true;
476	}
